import java.io.*;
import java.util.Base64;

public final class ConfigCenterClient {
    static class DataSourceConfig implements Serializable { private static final long serialVersionUID = 1L; String url; int maxPoolSize; }
    static class ThreadPoolConfig implements Serializable { private static final long serialVersionUID = 1L; int coreSize; int maxSize; }
    /** 白名单：枚举精确允许集，仅列出的配置类型可被反序列化 */
    private enum AllowedConfig {
        DATASOURCE(DataSourceConfig.class), THREADPOOL(ThreadPoolConfig.class);
        final Class<?> type;
        AllowedConfig(Class<?> type) { this.type = type; }
        static AllowedConfig resolve(String name) {
            for (AllowedConfig a : values()) {
                if (a.name().equals(name)) { return a; }
            }
            return null;
        }
    }
    /** 入口：configName 为配置类型名，payloadB64 为配置中心下发的序列化字节 */
    public Object applyConfig(String configName, String payloadB64) throws Exception {
        AllowedConfig allowed = AllowedConfig.resolve(configName);
        if (allowed == null) {
            throw new SecurityException("config type not in whitelist: " + configName);
        }
        final Class<?> expected = allowed.type;
        byte[] payload = Base64.getDecoder().decode(payloadB64);
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(payload)) {
            @Override
            protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
                if (desc.getName().equals(expected.getName())) { return expected; }
                throw new ClassNotFoundException("rejected by whitelist: " + desc.getName());
            }
            @Override
            protected Class<?> resolveProxyClass(String[] interfaces) throws IOException, ClassNotFoundException {
                throw new ClassNotFoundException("proxy rejected by whitelist");
            }
        }) {
            Object cfg = in.readObject();
            if (!expected.isInstance(cfg)) {
                throw new SecurityException("deserialized type mismatch");
            }
            return cfg;
        }
    }
}

package main

import (
	"fmt"
	"net/http"
	"regexp"
)

// namePattern 含嵌套量词,在回溯型正则引擎中可触发 CWE-1333 灾难性回溯
var namePattern = regexp.MustCompile(`^([a-zA-Z0-9_-]+\.)*[a-zA-Z0-9_-]+$`)

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	// 限制请求体大小,防止超大输入放大处理成本
	r.Body = http.MaxBytesReader(w, r.Body, 8<<20)
	if err := r.ParseMultipartForm(4 << 20); err != nil {
		http.Error(w, "invalid form", http.StatusBadRequest)
		return
	}
	file, header, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "missing file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	name := header.Filename
	if len(name) > 255 {
		http.Error(w, "filename too long", http.StatusBadRequest)
		return
	}
	// Go regexp 基于 RE2 自动机:线性时间匹配,无回溯路径,嵌套量词不会退化
	if !namePattern.MatchString(name) {
		http.Error(w, "invalid filename", http.StatusBadRequest)
		return
	}
	fmt.Fprintf(w, "accepted %s", name)
}

func main() {
	http.HandleFunc("/upload", uploadHandler)
	http.ListenAndServe(":8080", nil)
}

